	c.now = c.now.Add(d)
	c.mu.Unlock()
}

func TestNewValidation(t *testing.T) {
	clock := &fakeClock{now: time.Unix(0, 0)}
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr bool
	}{
		{"valid", 1, 1, clock, false},
		{"nil clock defaults", 1, 1, nil, false},
		{"zero rate", 0, 1, clock, true},
		{"negative rate", -1, 1, clock, true},
		{"nan rate", math.NaN(), 1, clock, true},
		{"inf rate", math.Inf(1), 1, clock, true},
		{"zero burst", 1, 0, clock, true},
		{"negative burst", 1, -1, clock, true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.rate, tt.burst, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err=%v wantErr=%v", err, tt.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	type step struct {
		advance time.Duration
		n       int
		want    bool
	}

	tests := []struct {
		name  string
		rate  float64
		burst int
		steps []step
	}{
		{
			name:  "initial burst",
			rate:  1,
			burst: 2,
			steps: []step{{0, 1, true}, {0, 1, true}, {0, 1, false}},
		},
		{
			name:  "refill",
			rate:  2,
			burst: 2,
			steps: []step{
				{0, 2, true},
				{500 * time.Millisecond, 1, true},
				{0, 1, false},
				{500 * time.Millisecond, 1, true},
			},
		},
		{
			name:  "cap at burst",
			rate:  10,
			burst: 2,
			steps: []step{{0, 2, true}, {time.Second, 2, true}},
		},
		{
			name:  "n exceeds burst",
			rate:  1,
			burst: 2,
			steps: []step{{0, 3, false}},
		},
		{
			name:  "invalid n",
			rate:  1,
			burst: 1,
			steps: []step{{0, 0, false}, {0, -1, false}},
		},
		{
			name:  "fractional refill",
			rate:  1,
			burst: 1,
			steps: []step{
				{0, 1, true},
				{500 * time.Millisecond, 1, false},
				{500 * time.Millisecond, 1, true},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := &fakeClock{now: time.Unix(0, 0)}
			l, err := New(tt.rate, tt.burst, clock)
			if err != nil {
				t.Fatal(err)
			}

			for i, s := range tt.steps {
				clock.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d)=%v want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}
